import type { components, operations } from '../../api/schema';

/**
 * Client-side model, derived from the BFF's OpenAPI contract (src/api/schema.d.ts,
 * generated by `npm run generate:api`). If the API changes, these types change and
 * the compiler points at every affected line.
 *
 * Note what is NOT here: no ages, no "18 and over" rule, no sorting. The server
 * owns every business rule; the client only says what it wants to see.
 */
export type Book = components['schemas']['BookResponse'];
export type BooksPage = components['schemas']['BooksPageResponse'];

type GetBooksQuery = operations['GetBooks']['parameters']['query'];
export type AgeCategory = GetBooksQuery['ageCategory'];
export type BookFormat = NonNullable<GetBooksQuery['format']>;

/** What the UI asks the server for (paging is handled inside the API client). */
export type BooksRequest = Pick<GetBooksQuery, 'ageCategory' | 'format'>;

/** Display order of the two sections. */
export const AGE_CATEGORIES: readonly AgeCategory[] = ['adult', 'child'];

/** The two views the brief asks for. A union (not a boolean) so new filters are additive. */
export type BookFilter = 'all' | 'hardcover';

const FILTER_FORMATS: Readonly<Record<BookFilter, BookFormat | null>> = {
  all: null,
  hardcover: 'hardcover',
};

export function toBooksRequest(ageCategory: AgeCategory, filter: BookFilter): BooksRequest {
  const format = FILTER_FORMATS[filter];
  return format === null ? { ageCategory } : { ageCategory, format };
}
